import { describe, expect, it } from "vitest";

/**
 * AMO refuses a new add-on whose manifest does not state what it collects, and
 * only Firefox 140 onwards reads that statement. The manifest is generated by
 * `scripts/manifest.mjs`; this holds the generated Gecko manifest to the
 * privacy policy's claim that nothing leaves the device.
 */
const MANIFEST_MODULE = new URL("../../scripts/manifest.mjs", import.meta.url).href;

/** First Firefox release that reads `data_collection_permissions`. */
const FIRST_CONSENT_AWARE_FIREFOX = 140;

type GeckoSettings = {
  id: string;
  strict_min_version: string;
  data_collection_permissions?: { required: string[] };
};

type Manifest = { browser_specific_settings?: { gecko: GeckoSettings } };

type ManifestModule = { manifestFor: (target: string) => Manifest };

async function buildManifest(target: string): Promise<Manifest> {
  const { manifestFor } = (await import(MANIFEST_MODULE)) as ManifestModule;
  return manifestFor(target);
}

describe("Firefox data collection consent", () => {
  it("declares that the extension collects no data", async () => {
    // Act
    const manifest = await buildManifest("firefox");

    // Assert
    expect(manifest.browser_specific_settings?.gecko.data_collection_permissions).toEqual({
      required: ["none"],
    });
  });

  it("requires a Firefox that reads the declaration", async () => {
    // Act
    const manifest = await buildManifest("firefox");

    // Assert
    const minVersion = manifest.browser_specific_settings?.gecko.strict_min_version ?? "0";
    expect(Number.parseInt(minVersion, 10)).toBeGreaterThanOrEqual(FIRST_CONSENT_AWARE_FIREFOX);
  });

  it("keeps Gecko settings out of the Chromium manifest", async () => {
    // Act
    const manifest = await buildManifest("chrome");

    // Assert
    expect(manifest.browser_specific_settings).toBeUndefined();
  });
});
